const REORDER_ONE_FN = (kLocal, startQi, planJson, mapJson2, quirksJson2) => {
  const norm = (s) => {
    s = (s || '').replace(/\s+/g, ' ').trim();
    s = s.replace(/^[^\p{L}]+/u, '').replace(/[^\p{L}]+$/u, '');
